create or replace function public.navilo_link_return_stock_movement() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ begin if lower(coalesce(new.type,'')) in ('sale_return','purchase_return') and new.source_id is null and nullif(btrim(coalesce(new.reference,'')),'') is not null then select rn.id into new.source_id from public.return_notes rn where rn.company_id=new.company_id and rn.note_no=new.reference and ((lower(new.type)='sale_return' and rn.note_type='sales_credit') or (lower(new.type)='purchase_return' and rn.note_type='purchase_debit')) order by rn.created_at desc limit 1; if new.source_id is not null then new.source_type:='return_note'; end if; end if; return new; end; $$; drop trigger if exists trg_link_return_stock_movement on public.stock_movements; create trigger trg_link_return_stock_movement before insert on public.stock_movements for each row execute function public.navilo_link_return_stock_movement();

